--
-- Table structure for table `courses`
--

DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `courses` (
  `id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程ID',
  `course_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程名称',
  `course_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程代码',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '课程描述',
  `teacher_id` bigint DEFAULT NULL COMMENT '教师ID',
  `duration` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程时长',
  `difficulty` enum('入门','基础','进阶','高级') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '基础' COMMENT '难度',
  `tags` json DEFAULT NULL COMMENT '标签(JSON数组)',
  `status` enum('draft','published','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '状态',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_course_name` (`course_name`),
  KEY `idx_teacher_id` (`teacher_id`),
  KEY `idx_status` (`status`),
  CONSTRAINT `courses_ibfk_1` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课程表';
