INSERT INTO `java_quiz` VALUES (1,'02_基本数据类型与运算符','Q001','下列选项中，哪个关键字用于声明一个变量为常量？','const','final','static','volatile','B','','2026-06-06 10:36:19'),(2,'02_基本数据类型与运算符','Q002','下列选项中，哪个不是Java中的基本数据类型？','byte','double','boolean','object','D','','2026-06-06 10:36:19'),(3,'02_基本数据类型与运算符','Q003','以下声明合法的选项是？','`default String s;`','`public final static native int w();`','`abstract double d;`','`abstract final double hyperbolicCosine();`','B','在Java中，`native`修饰的方法可以没有方法体，但`abstract`方法不能`final`同时修饰。','2026-06-06 10:36:19'),(4,'04_方法','Q004','为AB类的一个无形式参数无返回值的方法method书写方法头，使得使用类名（AB）作为前缀就可以调用它，该方法头的形式为？','`static void method()`','`public void method()`','`final void method()`','`abstract void method()`','A','直接用类名调用的是静态方法，用static修饰即可。','2026-06-06 10:36:19'),(5,'02_基本数据类型与运算符','Q005','以下哪一项是Java中合法的标识符？','`Tree&Glasses`','`FirstJavaApplet`','`*theLastOne`','`273.5`','B','Java标识符由字母、数字、下划线和美元符号组成，且不能以数字开头。','2026-06-06 10:36:19'),(6,'02_基本数据类型与运算符','Q006','下列哪个是合法的变量名？（多选）','`2variable`','`variable2`','`_whatavariable`','`_3_`\n- E. `$anothervar`\n- F. `#myvar`\n- G. `$_￥`','D,','变量名不能以数字开头，不能包含`.`、空格和`#`。','2026-06-06 10:36:19'),(7,'00_补充知识点','Q007','下面程序执行后b的值是？','9','true','1','false','B','在Java中，所有类都继承自Object类，Integer对象肯定是Object的实例。','2026-06-06 10:36:19'),(8,'06_字符串','Q008','在Java中，`String str = \"abc\"`，其中的`\"abc\"`分配在内存的哪个区域？','堆','栈','字符串常量区','寄存器','C','用双引号引起来的字符串字面量，存储在字符串常量池中。','2026-06-06 10:36:19'),(9,'01_Java历史背景与特点','Q009','下面哪个选项中，不属于Java语言的特点？','面向对象','高安全性','平台无关','面向过程','D','Java是面向对象的程序设计语言。','2026-06-06 10:36:19'),(10,'00_补充知识点','Q010','阅读下面代码，输出结果是什么？','`value is 99.9`','`value is 9`','`value is 9.0`','编译错误','C','三目运算符中，两个选项99.9（double）和9（int）的类型不同，自动取精度更高的类型，因此9被转为9.0。','2026-06-06 10:36:19'),(11,'07_类与对象','Q011','下列哪个类的声明是正确的？','`abstract final class HI{}`','`abstract private move(){}`','`protected private number;`','`public abstract class Car{}`','D','abstract和final不能同时修饰一个类；修饰符不能重复。','2026-06-06 10:36:19'),(12,'07_类与对象','Q012','关于被私有访问控制符private修饰的成员变量，以下说法正确的是？','可以被三种类所引用：该类自身、与它在同一个包中的其他类、在其他包中的该类的子类','可以被两种类访问和引用：该类本身、该类的所有子类','只能被该类自身所访问和修改','只能被同一个包中的类访问','C','private是最严格的访问权限，仅对当前类可见。','2026-06-06 10:36:19'),(13,'07_类与对象','Q013','现有父类A，子类B，B的子类C，在Java源代码中有如下声明：','只有第1行能通过编译','第1、2行能通过编译，但第3行编译出错','第1、2、3行能通过编译，但第2、3行运行时出错','第1行、第2行和第3行的声明都是正确的','D','继承具有传递性，C也是A的子类，所以可以将子类的实例赋值给父类的引用。','2026-06-06 10:36:19'),(14,'04_方法','Q014','下面关于方法覆盖的说法不正确的是？','方法覆盖要求覆盖和被覆盖的方法有相同的名字，参数列以及返回值','方法覆盖要求覆盖和被覆盖的方法必须具有相同的访问权限','覆盖的方法不能比被覆盖的方法抛出更多的异常','覆盖的方法一定不能是private的','B','子类覆盖方法的访问权限可以比父类更宽松，但不能更严格。','2026-06-06 10:36:19'),(15,'07_类与对象','Q015','下列有关继承的说法，正确的是？','子类能继承父类的所有方法和属性','子类能继承父类的非私有方法和属性','子类只能继承父类public方法和属性','子类能继承父类的方法，而不是属性','B','子类会继承父类所有非私有的属性和方法。','2026-06-06 10:36:19'),(16,'10_抽象类与接口','Q016','下面哪个关键字用于在Java中定义一个接口？','interface','abstract','class','method','A','`interface`关键字用于定义接口。','2026-06-06 10:36:19'),(17,'07_类与对象','Q017','在使用interface声明一个接口时，只可以使用哪个修饰符修饰该接口？','private','protected','private protected','public','D','接口可以是public的，也可以是默认的（default），但不能是private或protected。','2026-06-06 10:36:19'),(18,'07_类与对象','Q018','在Java中用什么关键字修饰的方法可以直接通过类名来调用？','static','final','private','void','A','静态方法（static修饰）属于类本身，可以直接通过类名调用。','2026-06-06 10:36:19'),(19,'10_抽象类与接口','Q019','以下哪个关于抽象类的描述是错误的？','abstract关键字可以修饰类或方法','final类的方法都不能是abstract，因为final类不能有子类','abstract类不能实例化','abstract类的子类必须实现其超类的所有abstract方法','D','如果抽象类的子类也是抽象的，可以不实现父类的抽象方法。','2026-06-06 10:36:19'),(20,'06_字符串','Q020','`String str1 = \"abc\"`，`String str2 = new String(\"abc\")`，那么`str1 == str2`的结果是？','true','false','','','B','`==`比较的是对象的引用地址，`str1`指向字符串常量池，`str2`指向堆内存中的对象，二者地址不同。','2026-06-06 10:36:19'),(21,'10_抽象类与接口','Q021','某类中有如下方法：`abstract void performDial();`，该方法属于？','接口方法','最终方法','抽象方法','空方法','C','由`abstract`修饰且没有方法体的方法是抽象方法。','2026-06-06 10:36:19'),(22,'07_类与对象','Q022','以下关于继承和实现说法正确的是？','类可以实现多个接口，接口可以继承（或扩展）多个接口','类可以实现多个接口，接口不能继承（或扩展）多个接口','类和接口都可以实现多个接口','类和接口都不可以实现多个接口','A','类可以`implements`多个接口，接口可以`extends`多个接口。','2026-06-06 10:36:19'),(23,'02_基本数据类型与运算符','Q023','假设A类有如下定义，设a是A类的一个实例，下列语句调用哪个是错误的？','`System.out.println(a.i);`','`a.method1();`','`A.method1();`','`A.method2();`','C','`method1()`是实例方法，必须通过对象来调用，不能直接通过类名调用。','2026-06-06 10:36:19'),(24,'07_类与对象','Q024','如果想使某个变量只可以被类本身访问和调用，应使用哪种访问控制修饰符？','private','protected','private protected','public','A','只有`private`修饰的成员只能在本类中被访问。','2026-06-06 10:36:19'),(25,'04_方法','Q025','下面说法不正确的是？','一个子类的对象可以接收父类对象能接收的消息','当子类对象和父类对象能接收同样的消息时，它们针对消息产生的行为可能不同','父类比它的子类的方法更多','子类在构造函数中可以使用super()来调用父类的构造函数','C','子类在继承父类方法的同时，还可以扩展自己的方法，因此子类的方法通常比父类更多。','2026-06-06 10:36:19'),(26,'00_补充知识点','Q026','下面这三条语句的输出结果分别是？','`is 1005`, `1005 is`, `is 1005`','`is 105`, `105 is`, `is 105`','`is 1005`, `105 is`, `is 105`','`is 1005`, `1005 is`, `is 105`','C','字符串拼接时，只要遇到字符串，整个表达式就转为字符串操作。但括号内会优先进行算术运算。','2026-06-06 10:36:19'),(27,'03_控制结构','Q027','下面关于for循环和while循环的说法中哪个是正确的？','while循环能实现的操作，for循环也都能实现','while循环判断条件一般是程序结果，for循环判断条件一般是非程序结果','两种循环任何时候都可替换','两种循环结构中都必须有循环体，循环体不能为空','A','for循环和while循环在功能上是等价的，可以相互转换。','2026-06-06 10:36:19'),(28,'03_控制结构','Q028','下面哪一个循环会导致死循环？','`for (int k = 0; k < 0; k++)`','`for (int k = 10; k > 0; k--)`','`for (int k = 0; k < 10; k--)`','`for (int k = 0; k > 0; k++)`','C','变量k从0开始，每次减1，永远小于10，循环条件始终为true，造成死循环。','2026-06-06 10:36:19'),(29,'00_补充知识点','Q029','执行如下程序段后，total的值为？','0','1','3','6','A','i=0时，total加0；i=1时，continue跳出本次循环；i=2时，break终止整个循环，因此total始终为0。','2026-06-06 10:36:19'),(30,'00_补充知识点','Q030','关于以下程序段，正确的说法是？','第4行与第6行都将执行','第4行执行，第6行不执行','第6行执行，第4行不执行','第4行、第6行都不执行','C','`s1`来自常量池，`s2`通过new在堆中创建，`==`比较地址为false；`equals()`比较内容为true。','2026-06-06 10:36:19'),(31,'00_补充知识点','Q031','`Math.round(-2.5)` 的结果是多少？','-2','-3','-2.5','-3.5','A','`round()`函数在数轴上是向右取整，`-2.5`向右取整为`-2`。','2026-06-06 10:36:19'),(32,'02_基本数据类型与运算符','Q032','`int a = -2`，则表达式 `a>>>3` 的值为？','0','3','8','-1','A','`>>>`是无符号右移，无论正负，高位都补0。`-2`的二进制右移3位后变为全0，结果是0。','2026-06-06 10:36:19'),(33,'00_补充知识点','Q033','下面代码的输出结果是什么？','2530','55','2052055','25255','D','先计算括号内的算术运算，遇到字符串后，后面的加号都变成字符串拼接。','2026-06-06 10:36:19'),(34,'02_基本数据类型与运算符','Q034','`System.out.println(\"5\" + 2);`的输出结果应该是？','52','7','2','5','A','字符串在前，加号被解释为字符串连接符，将数字2转为字符串拼接到后面。','2026-06-06 10:36:19'),(35,'03_控制结构','Q035','下列关于`for`循环和`while`循环的说法中哪个是正确的？','`while`循环能实现的操作，`for`循环也都能实现','`while`循环判断条件一般是程序结果，`for`循环判断条件一般是非程序结果','两种循环任何时候都可替换','两种循环结构中都必须有循环体，循环体不能为空','A','`for`循环是`while`循环的增强形式，功能上完全等价，可以相互转换。','2026-06-06 10:36:19'),(36,'02_基本数据类型与运算符','Q036','以下哪个运算符在Java中用于逻辑非操作？','!','#','%','/','A','`!`是逻辑非运算符，用于取反布尔值。','2026-06-06 10:36:19'),(37,'02_基本数据类型与运算符','Q037','设有数组的定义 `int[] a = new int[3]`，则下面对数组元素的引用错误的是？','`a[0];`','`a[];`','`a[3];`','`int i=1; a[i];`','B, C','`a[]`是错误语法；`a[3]`下标越界，最大索引是2。','2026-06-06 10:36:19'),(38,'03_控制结构','Q038','下列循环语句序列执行完成后，i的值是？','2','10','11','不确定','C','循环条件`i<=10`，当`i=11`时循环结束，此时i的值为11。','2026-06-06 10:36:19'),(39,'00_补充知识点','Q039','阅读以下代码，输出结果应该是？','2 2 2','2 3 3','2 2 3','3 4 4','C','`c++`是后置自增，先输出当前值2，再自增为3。','2026-06-06 10:36:19'),(40,'03_控制结构','Q040','下列哪一个关键字用于终止当前循环，并开始下一次循环迭代？','break','continue','return','exit','B','`continue`用于跳过本次循环的剩余部分，立即开始下一次迭代。','2026-06-06 10:36:19'),(41,'13_多线程与异常','Q041','下列哪个选项是Java中用于处理异常的关键字？（多选）','catch','throw','try','finally','A, C, D','`try`、`catch`、`finally`是异常处理的关键字，`throw`和`throws`用于抛出异常。','2026-06-06 10:36:19'),(42,'13_多线程与异常','Q042','下面关键字中，哪一个不是用于异常处理语句？','try','break','catch','finally','B','`break`用于跳出循环或switch语句，不属于异常处理关键字。','2026-06-06 10:36:19'),(43,'13_多线程与异常','Q043','假定一个方法会产生非RuntimeException异常，如果希望把异常交给调用该方法的方法处理，正确的声明方式是什么？','`throw Exception`','`throws Exception`','`new Exception`','不需要指明什么','B','`throws`用在方法声明后面，表示该方法可能抛出的异常，由调用者处理。','2026-06-06 10:36:19'),(44,'13_多线程与异常','Q044','以下对异常的描述不正确的是？','异常分为Error和Exception','Throwable是所有异常类的父类','在程序中无论是Error类型，还是Exception类型的异常，都可以捕获后进行异常处理','Exception是RuntimeException异常的父类','C','Error通常是系统级错误，程序无法处理，也不应该捕获。','2026-06-06 10:36:19'),(45,'13_多线程与异常','Q045','执行下面程序的结果是什么？（其中a=4,b=0）','`Exception Finally`','`Finally`','`Exception`','没有输出结果','A','除零异常触发`catch`块，且无论是否异常`finally`块都会执行。','2026-06-06 10:36:19'),(46,'02_基本数据类型与运算符','Q046','在Java中，Character流与Byte流的区别是？','每次读入的字节数不同','前者带有缓冲，后者没有','前者是字符读写，后者是字节读写','二者没有区别，可以互换使用','C','字节流以字节为单位，字符流以字符为单位，处理文本文件时更推荐字符流。','2026-06-06 10:36:19'),(47,'02_基本数据类型与运算符','Q047','要从文件\"file.dat\"中读出第10个字节到变量c中，下列哪个方法适合？','`FileInputStream in=new FileInputStream(\"file.dat\"); in.skip(9); int c=in.read();`','`FileInputStream in=new FileInputStream(\"file.dat\"); in.skip(10); int c=in.read();`','`FileInputStream in=new FileInputStream(\"file.dat\"); int c=in.read();`','`RandomAccessFile in=new RandomAccessFile(\"file.dat\"); in.skip(9); int c=in.readByte();`','D','`RandomAccessFile`可以跳过9个字节后读取第10个字节。`FileInputStream`顺序读取，不适合。','2026-06-06 10:36:19'),(48,'00_补充知识点','Q048','Java编程所必须的默认引用包为？','`java.sys`','`java.lang`','`java.util`','以上都不是','B','`java.lang`包是Java语言的核心包，使用前不需要`import`。','2026-06-06 10:36:19'),(49,'07_类与对象','Q049','欲构造ArrayList类的一个实例，此类继承了List接口，下列哪个方法是正确的？','`ArrayList myList = new Object();`','`List myList = new ArrayList();`','`ArrayList myList = new List();`','`List myList = new List();`','B','ArrayList是List接口的实现类，可以通过父类引用指向子类对象，但List是接口不能实例化。','2026-06-06 10:36:19'),(50,'00_补充知识点','Q050','下列哪个集合类实现了队列的接口？','ArrayList','LinkedList','HashSet','HashMap','B','LinkedList实现了Queue接口，可以用作队列数据结构。','2026-06-06 10:36:19'),(51,'02_基本数据类型与运算符','Q051','关于下面程序，以下哪种描述是正确的？','5行不能通过编译，因为引用了私有静态变量','10行不能通过编译，因为x是私有静态变量','程序通过编译，输出结果为：x=103','程序通过编译，输出结果为：x=102','D','虽然x是private，但在类内部可以访问。静态变量属于类，所有实例共享同一个x。','2026-06-06 10:36:19'),(52,'05_数组','Q052','`ArrayList list = new ArrayList(20);`中的list扩充了几次？','0','1','2','3','A','当指定初始容量时，ArrayList会直接分配相应大小的数组，不会立即发生扩容。','2026-06-06 10:36:19'),(53,'00_补充知识点','Q053','下面哪些接口直接继承自Collection接口？（多选）','List','Map','Set','Iterator','A, C','Map是独立的接口，Iterator不是Collection的子接口。','2026-06-06 10:36:19'),(54,'00_补充知识点','Q054','关于List和Set的区别，说法正确的是？','List元素有放入顺序，元素可重复；Set元素无放入顺序，元素不可重复','List元素无放入顺序，元素可重复；Set元素有放入顺序，元素不可重复','List和Set都有放入顺序，元素都可重复','List和Set都无放入顺序，元素都不可重复','A','List有序可重复，Set无序不可重复。','2026-06-06 10:36:19'),(55,'00_补充知识点','Q055','下面选项中哪一个是正确的创建Map集合的方式？','`Map m = new Map();`','`Map m = new Map(init capacity, increment capacity);`','`Map m = new Map(new Collection());`','Map是接口，不能实例化。','D','Map是接口，需要通过实现类如HashMap来实例化。','2026-06-06 10:36:19'),(56,'10_抽象类与接口','Q056','以下哪个接口用于实现迭代器功能？','Iterable','Iterator','Collection','List','B','Iterator接口定义了hasNext()和next()等方法，用于遍历集合。','2026-06-06 10:36:19'),(57,'00_补充知识点','Q057','关于HashSet的说法正确的是？','HashSet继承自AbstractSet','HashSet继承自HashMap','HashSet继承自Collection','HashSet继承自List','A','HashSet继承自AbstractSet，同时实现了Set接口。','2026-06-06 10:36:19'),(58,'00_补充知识点','Q058','在Java中，使用JDBC时，对于多次调用同一条SQL语句的情况，使用哪个通常会提高效率？','Statement','CallableStatement','PreparedStatement','SQLStatement','C','PreparedStatement会预编译SQL语句，多次执行时效率更高。','2026-06-06 10:36:19'),(59,'02_基本数据类型与运算符','Q059','在Java类中，使用以下哪个声明语句来定义公有的int型常量MAX？','`int MAX = 100;`','`final int MAX = 100;`','`public static int MAX = 100;`','`public static final int MAX = 100;`','D','常量需同时用`public static final`修饰，变量名通常全大写。','2026-06-06 10:36:19'),(60,'07_类与对象','Q060','下面的对象创建方法中哪些会调用构造方法？（多选）','new语句创建对象','调用java.io.ObjectInputStream的readObject方法','java反射机制使用java.lang.Class或java.lang.reflect.Constructor的newInstance()方法','调用对象的clone()方法','A, C','序列化的`readObject()`和`clone()`方法均不会调用构造器。','2026-06-06 10:36:19'),(61,'02_基本数据类型与运算符','Q061','请问，以下哪些是Java中合法的标识符？（多选）','`_xpoints`','`r2d2`','`bbb$`','`set-flow`\n- E. `thisiscrazy`','A, B, C,','标识符只能由字母、数字、下划线和美元符号组成，且不能以数字开头，不能包含连接符。','2026-06-06 10:36:19'),(62,'02_基本数据类型与运算符','Q062','下面哪个是合法的数组声明和构造语句？','`int[] ages = [100];`','`int ages = new int[100];`','`int[] ages = new int[100];`','`int() ages = new int(100);`','C','Java中标准的数组声明方式是`type[] varName = new type[size];`。','2026-06-06 10:36:19'),(63,'02_基本数据类型与运算符','Q063','下面声明数组的写法错误的是？（多选）','`int a[];`','`int[] a;`','`int[3][] a;`','`int[][3] a;`','C, D','Java中声明数组时，不能在方括号内指定大小，大小是在创建对象时指定的。','2026-06-06 10:36:19'),(64,'04_方法','Q064','在Java中，如果要让线程执行，应该调用哪个方法？','run()','start()','execute()','init()','B','`start()`会启动新线程，新线程执行`run()`方法；直接调用`run()`只是普通方法调用。','2026-06-06 10:36:19'),(65,'13_多线程与异常','Q065','在Servlet处理请求的方式为？','以进程的方式','以程序的方式','以线程的方式','以响应的方式','C','Servlet容器为每个请求创建一个线程来处理，而非进程。','2026-06-06 10:36:19'),(66,'13_多线程与异常','Q066','以下哪个方法用于定义线程的执行体？','start()','init()','run()','synchronized()','C','`run()`方法中包含线程要执行的代码，是线程的执行体。','2026-06-06 10:36:19'),(67,'04_方法','Q067','下列方法中哪个是线程执行的方法？','run()','start()','sleep()','suspend()','A','`run()`是线程的入口，包含线程执行的代码。','2026-06-06 10:36:19'),(68,'07_类与对象','Q068','哪个关键字可以对对象加互斥锁？','transient','synchronized','serialize','static','B','`synchronized`用于线程同步，对对象或代码块加锁。','2026-06-06 10:36:19'),(69,'07_类与对象','Q069','下面哪个不是Object类的方法？','wait()','notify()','notifyAll()','sleep()','D','`sleep()`是Thread类的静态方法，属于线程操作，不在Object类中。','2026-06-06 10:36:19'),(70,'04_方法','Q070','关于线程状态，以下描述正确的是？','线程创建后立即进入运行状态','线程调用`start()`方法后立即进入运行状态','线程调用`sleep()`方法会进入阻塞状态','线程终止后可以再次调用`start()`重新启动','C','`sleep()`使线程进入阻塞状态；`start()`使线程进入就绪态，等待CPU调度；终止的线程不能重新启动。','2026-06-06 10:36:19'),(71,'00_补充知识点','Q071','JDBC中，用于表示数据库连接的对象是？','Statement','Connection','DriverManager','PreparedStatement','B','`Connection`代表与特定数据库的连接会话。','2026-06-06 10:36:19'),(72,'00_补充知识点','Q072','用于调用存储过程的对象是？','ResultSet','DriverManager','CallableStatement','PreparedStatement','C','`CallableStatement`用于执行数据库中的存储过程。','2026-06-06 10:36:19'),(73,'00_补充知识点','Q073','获取ResultSet对象rst的下一行数据，以下正确的是？','`rst.hasNext()`','`rst.next()`','`rst.first()`','`rst.nextRow()`','B','JDBC中ResultSet的`next()`方法用于将光标从当前位置移到下一行。','2026-06-06 10:36:19'),(74,'00_补充知识点','Q074','ResultSet常用定位方法boolean next()的作用是？','定位到指定编号的记录上','定位到第一行','定位到最后一行','从前往后移动一行','D','`next()`将光标从当前位置向下移动一行，如果没有下一行则返回false。','2026-06-06 10:36:19'),(75,'00_补充知识点','Q075','如果数据库中某个字段为numeric型，可以通过结果集中的哪个方法获取？','`getNumberic()`','`getDouble()`','`setNumberic()`','`setDouble()`','B','JDBC中numeric类型通常可以通过`getDouble()`或`getBigDecimal()`获取。','2026-06-06 10:36:19'),(76,'00_补充知识点','Q076','在Java中开发JDBC应用程序时，使用DriverManager类的getConnection()方法建立与数据源的连接语句为：`Connection con = DriverManager.getConnection(\"jdbc:microsoft:sqlserver://localhost:1433;DatabaseName=news\");`。URL连接中的“news”表示的是？','用户名','数据库的名称','数据库服务器的机器名','数据库中表的名称','B','JDBC URL中DatabaseName参数指定要连接的数据库实例。','2026-06-06 10:36:19'),(77,'00_补充知识点','Q077','若要在Java中表示一个空引用，应该使用什么？','null','0','\"\"','false','A','`null`是Java中专门表示引用不指向任何对象的字面量。','2026-06-06 10:36:19'),(78,'00_补充知识点','Q078','下面哪一个是正确的Java注释方式？（多选）','`// 这是单行注释`','`/* 这是多行注释 */`','`# 这是注释`','`-- 这是注释`','A, B','Java支持`//`和`/* */`两种注释方式，不支持`#`。','2026-06-06 10:36:19'),(79,'02_基本数据类型与运算符','Q079','下面哪个是Java中的基本数据类型？','Integer','String','Boolean','ArrayList','C','Java基本数据类型包括byte、short、int、long、float、double、char、boolean。Boolean是包装类。','2026-06-06 10:36:19'),(80,'06_字符串','Q080','在Java中，如何将一个字符串转换为整数？','`Integer.parseInt()`','`String.toInt()`','`(int)String`','`int.valueOf(String)`','A','`Integer.parseInt()`是将字符串转换为int类型的最标准方法。','2026-06-06 10:36:19'),(81,'07_类与对象','Q081','在Java中，以下哪个访问修饰符具有最大的访问权限？','private','protected','public','default','C','访问权限从大到小为：public > protected > default > private。','2026-06-06 10:36:19'),(82,'03_控制结构','Q082','关于`break`和`continue`的说法，正确的是？','`break`跳出当前循环，`continue`结束本次循环继续下一次','`break`结束本次循环继续下一次，`continue`跳出当前循环','`break`和`continue`可以互相替换','`break`和`continue`只能用在`for`循环中','A','`break`终止循环，`continue`跳过本次循环的剩余部分，继续下一次迭代。','2026-06-06 10:36:19'),(83,'07_类与对象','Q083','要使对象具有序列化能力，则其类应该实现如下哪个接口？','Serializable','Cloneable','Runnable','Comparable','A','实现`java.io.Serializable`接口可使对象被序列化。','2026-06-06 10:36:19'),(84,'13_多线程与异常','Q084','下面哪个关键字用于在Java中显式地抛出一个异常？','throw','exception','catch','try','A','`throw`用于在代码中显式抛出一个异常对象。','2026-06-06 10:36:19'),(85,'07_类与对象','Q085','在Java中，用于定义类的关键字是？','interface','class','struct','object','B','`class`关键字用于定义类。','2026-06-06 10:36:19'),(86,'07_类与对象','Q086','下面关于`main`方法的说法正确的是？','`public main(String args[])`','`public static void main(String args[])`','`private static void main(String args[])`','`void main()`','B','`main`方法的正确签名是`public static void main(String[] args)`。','2026-06-06 10:36:19');
