/*!40000 ALTER TABLE `learning_path_history` DISABLE KEYS */;
INSERT INTO `learning_path_history` VALUES (1,4,'完成 JavaSE 学习','{\"exam\": [\"Set框架：ArrayList、LinkedList、HashMap 的底层原理与常见面试题\", \"IO流：byte流、char流、缓冲流、序列化\", \"多线程：Thread/Runnable、synchronized、并发容器基础\"], \"week\": [\"掌握基本语法：变量、运算符、流程控制（if/switch/for/while）\", \"面向Object核心：构造方法、this、static、封装、继承、多态、interface\", \"异常处理与常用API：try-catch、throws、StringBuilder、package装class\"], \"today\": [\"1. 验证JDK环境：在命令行输入 `java -version` 和 `javac -version`，确保两者都显示版本号；若路径错误，重new配置 PATH 指向 bin 目录，**必须关闭并重开命令行**后再验证\", \"2. 用记事本编写一个 HelloWorld.java，编译运行成功，代码内package含 System.out.println(LocalDate.now()) println今日日期\", \"3. 将下面的代码示例（时间API练习）完整抄写并运行，观察println\"], \"practice\": [\"项目一：控制台版 \'学生信息管理系统\'（增删改查，数据存文件）\", \"项目二：简易 \'日记本\' 程序（支持日期查询，使用 LocalDate 和 DateTimeFormatter）\", \"项目三：多线程 \'模拟售票窗口\'（练习线程安全）\"]}','2026-06-03 11:29:41'),(2,4,'完成JavaSE学习','{\"exam\": [\"数组与方法的综合练习题（冒泡排序、数组反转）\", \"面向Object基础：class、Object、构造方法、封装\"], \"goal\": \"完成JavaSE学习\", \"week\": [\"完成变量、数据class型、运算符的代码练习\", \"完成流程控制（if/switch/for/while）的10道例题\"], \"today\": [\"验证javac和java命令可用\", \"编写并运行第一个HelloWorld程序\"], \"practice\": [\"用class写一个学生成绩管理系统（数组 + 方法）\", \"implements简易计算器（控制台交互）\"], \"study_time\": \"每天固定1小时，周末2小时。先跑通今天的任务，再continue\", \"exam_advice\": \"重点掌握面向Object三大特征、异常处理、常用API（String、ArrayList）\", \"suggestions\": \"每学一个知识点，立刻写3~5行代码验证。不要只看不敲\"}','2026-06-03 11:47:22'),(3,4,'完成 JavaSE 学习','{\"exam\": [\"完成 10 道 Java 基础选择题，覆盖作用域、重载、继承、异常\", \"手写一道编程题：逆序输出数组元素，考察数组和循环\"], \"goal\": \"完成 JavaSE 学习\", \"week\": [\"掌握基础语法：变量、数据类型、运算符、流程控制（if/switch/for/while）\", \"学习面向对象核心：class、对象、构造方法、this、static、封装、继承、多态\", \"练习常用 API：String、StringBuilder、包装类、日期类（LocalDate 等）\"], \"today\": [\"验证 JDK 安装与 PATH 配置：在 cmd 输入 java -version 和 javac -version，确认版本\", \"编写并运行第一个 HelloWorld.java，体会 javac 和 java 命令的流程\"], \"practice\": [\"每天至少写 2 个完整代码（包括 main 方法）并编译运行\", \"将遇到的错误记录到文档，逐步熟悉编译时和运行时错误\"], \"study_time\": \"每天晚上 20:00-21:30，周末上午 10:00-12:00，雷打不动\", \"exam_advice\": \"考试前重点复习：封装继承多态的实际应用、try-catch 的书写形式、String 与 StringBuilder 的区别。判断题陷阱多，看清变量作用域。\", \"suggestions\": \"不要反复规划，现在就开始写代码。环境配置再卡住就重新看 bin 目录的路径，改完环境变量必须新开命令行窗口才生效。先动手指，问题自然暴露。\"}','2026-06-03 11:47:23');
