INSERT INTO `learning_paths` VALUES (1,4,'{\"goal\":\"掌握线程创建、同步机制和线程池使用\",\"targetMastery\":\"≥85%\",\"estimatedCompletion\":\"2025-07-15\",\"totalTasks\":10,\"completedTasks\":1,\"totalHours\":18,\"stages\":[{\"name\":\"今日计划\",\"tasks\":[{\"id\":null,\"title\":\"通过代码案例理解Thread类与Runnable接口创建线程\",\"description\":null,\"dueDate\":null,\"status\":2,\"priority\":null,\"createTime\":null,\"duration\":30,\"progress\":100},{\"id\":null,\"title\":\"阅读讲解文档：线程生命周期与状态转换\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":30,\"progress\":0}]},{\"name\":\"本周路径\",\"tasks\":[{\"id\":null,\"title\":\"动手编写synchronized同步代码块案例，观察线程安全效果\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":45,\"progress\":0},{\"id\":null,\"title\":\"完成死锁排查练习题：分析并修复死锁代码\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":45,\"progress\":0},{\"id\":null,\"title\":\"学习讲解文档：synchronized底层原理与锁升级\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":45,\"progress\":0}]},{\"name\":\"考试冲刺\",\"tasks\":[{\"id\":null,\"title\":\"模拟面试题练习：线程安全与同步机制综合题\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":60,\"progress\":0},{\"id\":null,\"title\":\"代码案例实战：使用ReentrantLock替代synchronized并对比\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":60,\"progress\":0},{\"id\":null,\"title\":\"死锁检测与排查专项练习（jstack工具使用）\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":60,\"progress\":0}]},{\"name\":\"实践提升\",\"tasks\":[{\"id\":null,\"title\":\"基于线程池的并发任务调度案例（ThreadPoolExecutor配置与监控）\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":90,\"progress\":0},{\"id\":null,\"title\":\"综合练习题：设计一个线程安全的计数器类并验证\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":90,\"progress\":0}]}],\"suggestions\":\"根据慢速学习节奏，建议每个任务完成后休息10分钟，并重写代码加深印象。若某个薄弱点感觉吃力，可重复该阶段的相关练习题。\",\"applicationAdvice\":\"在实际项目中使用线程池管理并发任务，避免手动创建线程；通过日志和jstack定期排查死锁风险。\",\"examAdvice\":\"建议每完成一个阶段后做一次小测验，重点考核synchronized原理、死锁场景分析及线程池参数调优。\",\"resources\":null,\"adjustRecords\":null,\"masteryRate\":72,\"learningRate\":18,\"unmasteredRate\":10,\"recommendTime\":\"每天 19:00-21:00\"}',10,'slow','active','2026-06-06 18:00:01','2026-06-10 14:54:18','掌握线程创建、同步机制和线程池使用','不要反复规划，现在就开始写代码。环境配置再卡住就重新看 bin 目录的路径，改完环境变量必须新开命令行窗口才生效。先动手指，问题自然暴露。','[]','考试前重点复习：封装继承多态的实际应用、try-catch 的书写形式、String 与 StringBuilder 的区别。判断题陷阱多，看清变量作用域。'),(2,5,NULL,0,'slow','active','2026-05-31 17:06:40','2026-05-31 17:06:40',NULL,NULL,NULL,NULL),(3,6,NULL,20,'fast','active','2026-05-31 17:06:40','2026-05-31 17:06:40',NULL,NULL,NULL,NULL),(4,7,NULL,100,'medium','active','2026-05-31 17:06:40','2026-05-31 17:06:40',NULL,NULL,NULL,NULL),(5,9,NULL,0,'slow','active','2026-05-31 17:06:40','2026-05-31 17:06:40',NULL,NULL,NULL,NULL),(6,30,'{\"goal\":\"建立AI基础知识体系，掌握核心概念与入门实践\",\"targetMastery\":\"≥85%\",\"estimatedCompletion\":\"2025-06-30\",\"totalTasks\":11,\"completedTasks\":0,\"totalHours\":120,\"stages\":[{\"name\":\"今日计划\",\"tasks\":[{\"id\":null,\"title\":\"机器学习基本概念与分类\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":30,\"progress\":0},{\"id\":null,\"title\":\"监督学习与无监督学习区别\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":30,\"progress\":0}]},{\"name\":\"本周路径\",\"tasks\":[{\"id\":null,\"title\":\"线性回归原理与实现\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":45,\"progress\":0},{\"id\":null,\"title\":\"逻辑回归与分类任务\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":45,\"progress\":0},{\"id\":null,\"title\":\"决策树与随机森林入门\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":45,\"progress\":0}]},{\"name\":\"考试冲刺\",\"tasks\":[{\"id\":null,\"title\":\"神经网络基础与反向传播\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":60,\"progress\":0},{\"id\":null,\"title\":\"卷积神经网络(CNN)原理\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":60,\"progress\":0},{\"id\":null,\"title\":\"模型评估与调参技巧\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":60,\"progress\":0}]},{\"name\":\"实践提升\",\"tasks\":[{\"id\":null,\"title\":\"使用Scikit-learn完成分类项目\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":90,\"progress\":0},{\"id\":null,\"title\":\"搭建简单神经网络进行图像识别\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":90,\"progress\":0},{\"id\":null,\"title\":\"完整机器学习项目流程实战\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":90,\"progress\":0}]}],\"suggestions\":\"由于暂无画像数据，建议先完成基础概念学习，后续根据掌握情况动态调整学习重点。每周进行一次小测，及时弥补薄弱环节。\",\"applicationAdvice\":\"每学完一个算法，立即在Jupyter Notebook中动手实现并测试，将理论与实践结合。\",\"examAdvice\":\"每阶段结束后完成对应章节的练习题和模拟测验，重点关注模型评估指标和常见错误分析方法。\",\"resources\":null,\"adjustRecords\":null,\"masteryRate\":72,\"learningRate\":18,\"unmasteredRate\":10,\"recommendTime\":\"每天 19:00-21:00\"}',0,'medium','active','2026-06-08 09:40:55','2026-06-08 09:40:55','建立AI基础知识体系，掌握核心概念与入门实践',NULL,NULL,NULL),(7,34,'{\"goal\":\"完成课程学习目标\",\"targetMastery\":\"≥85%\",\"estimatedCompletion\":\"2026-07-08\",\"totalTasks\":8,\"completedTasks\":0,\"totalHours\":20,\"stages\":[{\"name\":\"今日计划\",\"tasks\":[{\"id\":null,\"title\":\"今日计划 - 任务1\",\"description\":null,\"dueDate\":null,\"status\":0,\"priority\":null,\"createTime\":null,\"duration\":30,\"progress\":0},{\"id\":null,\"title\":\"今