"共享变量与竞态条件\"},{\"id\":\"2-2\",\"topic\":\"synchronized 原理\",\"children\":[{\"id\":\"2-2-1\",\"topic\":\"对象锁与类锁\"},{\"id\":\"2-2-2\",\"topic\":\"同步代码块与方法\"},{\"id\":\"2-2-3\",\"topic\":\"锁的升级过程\"}]},{\"id\":\"2-3\",\"topic\":\"volatile 关键字\"},{\"id\":\"2-4\",\"topic\":\"原子类与CAS\"}]},{\"id\":\"3\",\"topic\":\"线程协作\",\"children\":[{\"id\":\"3-1\",\"topic\":\"wait/notify 机制\"},{\"id\":\"3-2\",\"topic\":\"CountDownLatch\"},{\"id\":\"3-3\",\"topic\":\"CyclicBarrier\"},{\"id\":\"3-4\",\"topic\":\"Semaphore\"}]},{\"id\":\"4\",\"topic\":\"锁与并发工具\",\"children\":[{\"id\":\"4-1\",\"topic\":\"ReentrantLock\"},{\"id\":\"4-2\",\"topic\":\"ReadWriteLock\"},{\"id\":\"4-3\",\"topic\":\"LockSupport\"},{\"id\":\"4-4\",\"topic\":\"阻塞队列\"}]},{\"id\":\"5\",\"topic\":\"死锁排查与预防\",\"children\":[{\"id\":\"5-1\",\"topic\":\"死锁产生条件\"},{\"id\":\"5-2\",\"topic\":\"死锁检测工具\"},{\"id\":\"5-3\",\"topic\":\"避免死锁策略\"}]},{\"id\":\"6\",\"topic\":\"线程池\",\"children\":[{\"id\":\"6-1\",\"topic\":\"核心参数解析\"},{\"id\":\"6-2\",\"topic\":\"任务提交与执行\"},{\"id\":\"6-3\",\"topic\":\"常见线程池类型\"},{\"id\":\"6-4\",\"topic\":\"线程池关闭\"}]},{\"id\":\"7\",\"topic\":\"实践与案例\",\"children\":[{\"id\":\"7-1\",\"topic\":\"代码案例：线程安全计数器\"},{\"id\":\"7-2\",\"topic\":\"代码案例：生产者消费者\"},{\"id\":\"7-3\",\"topic\":\"练习题：排查死锁\"},{\"id\":\"7-4\",\"topic\":\"讲解文档：synchronized 底层\"}]}]}',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'1780811837224','Java 程序设计',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-07 13:57:32','2026-06-07 13:57:32'),(170,'Java - 拓展阅读','reading','适合',NULL,'AI 生成失败，请稍后重试',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'0','Java',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-08 09:53:57','2026-06-08 09:53:57'),(171,'JavaSE - 学习路径','learning_path','medium',NULL,'{\n  \"goal\": \"掌握JavaSE循环结构（for、while、do-while）的语法与执行流程，能够正确使用循环解决常见问题，理解循环控制语句（break、continue）的作用，并能够熟练编写包含循环的简单程序。\",\n  \"stages\": [\n    {\n      \"name\": \"基础理解\",\n      \"tasks\": [\n        {\n          \"title\": \"学习for循环的语法和执行流程\",\n          \"duration\": 30,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"学习while循环的语法和执行流程\",\n          \"duration\": 25,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"学习do-while循环的语法和执行流程\",\n          \"duration\": 25,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"对比三种循环结构的特点与适用场景\",\n          \"duration\": 20,\n          \"status\": 0,\n          \"progress\": 0\n        }\n      ]\n    },\n    {\n      \"name\": \"循环控制\",\n      \"tasks\": [\n        {\n          \"title\": \"学习break语句在循环中的使用\",\n          \"duration\": 20,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"学习continue语句在循环中的使用\",\n          \"duration\": 20,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"练习使用break和continue控制循环流程\",\n          \"duration\": 30,\n          \"status\": 0,\n          \"progress\": 0\n        }\n      ]\n    },\n    {\n      \"name\": \"嵌套循环\",\n      \"tasks\": [\n        {\n          \"title\": \"学习嵌套循环的概念与执行过程\",\n          \"duration\": 20,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"练习嵌套循环打印图形（如矩形、三角形）\",\n          \"duration\": 30,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"练习嵌套循环解决数学问题（如乘法表）\",\n          \"duration\": 25,\n          \"status\": 0,\n          \"progress\": 0\n        }\n      ]\n    },\n    {\n      \"name\": \"综合应用\",\n      \"tasks\": [\n        {\n          \"title\": \"完成循环综合练习题（如数字求和、素数判断）\",\n          \"duration\": 40,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"编写一个使用循环实现的小项目（如猜数字游戏）\",\n          \"duration\": 45,\n          \"status\": 0,\n          \"progress\": 0\n        },\n        {\n          \"title\": \"总结循环常见错误与调试技巧\",\n          \"duration\": 20,\n          \"status\": 0,\n          \"progress\": 0\n        }\n      ]\n    }\n  ]\n}',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'34','JavaSE',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-08 15:56:50','2026-06-08 15:56:50'),(172,'JavaSE - 思维导图','mindmap','medium',NULL,'{\"id\":\"root\",\"topic\":\"JavaSE循环\",\"children\":[{\"id\":\"n1\",\"topic\":\"循环概述\",\"children\":[{\"id\":\"n11\",\"topic\":\"定义：重复执行代码块的结构\"},{\"id\":\"n12\",\"topic\":\"必要性：避免代码冗余，提高效率\"},{\"id\":\"n13\",\"topic\":\"基本要素：初始条件、循环条件、循环体、迭代\"}]},{\"id\":\"n2\",\"topic\":\"while 循环\",\"children\":[{\"id\":\"n21\",\"topic\":\"语法：while (条件) { 代码块 }\"},{\"id\":\"n22\",\"topic\":\"特点：先判断后执行，可能一次都不执行\"},{\"id\":\"n23\",\"topic\":\"示例：打印1到10的数字\"},{\"id\":\"n24\",\"topic\":\"注意事项：防止死循环，确保条件会变为false\"}]},{\"id\":\"n3\",\"topic\":\"do-while 循环\",\"children\":[{\"id\":\"n31\",\"topic\":\"语法：do { 代码块 } while (条件);\"},{\"id\":\"n32\",\"topic\":\"特点：先执行后判断，至少执行一次\"},{\"id\":\"n33\",\"topic\":\"应用场景：需要先执行一次再判断的情况\"},{\"id\":\"n34\",\"topic\":\"与while对比：执行次数差异\"}]},{\"id\":\"n4\",\"topic\":\"for 循环\",\"children\":[{\"id\":\"n41\",\"topic\":\"语法：for (初始化; 条件; 迭代) { 代码块 }\"},{\"id\":\"n42\",\"topic\":\"执行流程：初始化→判断→执行→迭代→再判断\"},{\"id\":\"n43\",\"topic\":\"常见用法：遍历数组或固定次数循环\"},{\"id\":\"n44\",\"topic\":\"示例：计算1到100的和\"},{\"id\":\"n45\",\"topic\":\"注意：变量作用域，初始化部分变量仅在循环内有效\"}]},{\"id\":\"n5\",\"topic\":\"循环控制语句\",\"children\":[{\"id\":\"n51\",\"topic\":\"break：立即跳出整个循环\"},{\"id\":\"n52\",\"topic\":\"continue：跳过本次循环，进入下一次迭代\"},{\"id\":\"n53\",\"topic\":\"区别：break终止循环，continue跳过当前轮\"},{\"id\":\"n54\",\"topic\":\"示例：查找第一个偶数用break，跳过奇数用continue\"}]},{\"id\":\"n6\",\"topic\":\"嵌套循环\",\"children\":[{\"id\":\"n61\",\"topic\":\"概念：循环体内包含另一个循环\"},{\"id\":\"n62\",\"topic\":\"应用：打印乘法表、二维数组遍历\"},{\"id\":\"n63\",\"topic\":\"执行顺序：外层循环一次，内层循环全部\"},{\"id\":\"n64\",\"topic\":\"性能提示：避免过深嵌套，优化循环次数\"}]},{\"id\":\"n7\",\"topic\":\"循环常见错误与调试\",\"children\":[{\"id\":\"n71\",\"topic\":\"死循环：条件永远为真\"},{\"id\":\"n72\",\"topic\":\"边界错误：多一次或少一次迭代\"},{\"id\":\"n73\",\"topic\":\"忘记更新迭代变量\"},{\"id\":\"n74\",\"topic\":\"调试方法：打印中间结果，检查条件\"}]}]}',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'34','JavaSE',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-08 15:56:57','2026-06-08 15:56:57'),(173,'JavaSE - 练习题目','quiz','medium',NULL,'AI 生成失败，请稍后重试',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'34','JavaSE',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-08 17:25:10','2026-06-08 17:25:10'),(174,'JavaSE - 拓展阅读','reading','medium',NULL,'AI 生成失败，请稍后重试',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'34','JavaSE',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-08 17:25:10','2026-06-08 17:25:10'),(175,'JavaSE - 代码案例','code','medium',NULL,'AI 生成失败，请稍后重试',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'34','JavaSE',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-08 17:25:10','2026-06-08 17:25:10'),(176,'Java - 代码案例','code','适合',NULL,'```java\n/**\n * 多线程与并发教学案例：模拟银行转账系统\n * 本案例演示：\n * 1. 线程安全问题（多个线程同时操作共享资源）\n * 2. synchronized 关键字的使用（同步方法/同步块）\n * 3. 死锁的模拟与排查思路\n * \n * 学习目标：\n * - 理解什么是竞态条件（Race Condition）\n * - 掌握 synchronized 的两种使用方式\n * - 学会识别并避免死锁\n */\npublic class BankTransferDemo {\n\n    // 共享资源：两个银行账户\n    private static Account accountA = new Account(\"张三\", 1000);\n    private static Account accountB = new Account(\"李四\", 1000);\n\n    public static void main(String[] args) throws InterruptedException {\n        System.out.println(\"========== 银行转账系统演示 ==========\");\n        System.out.println(\"初始状态：\");\n        System.out.println(accountA);\n        System.out.println(accountB);\n        System.out.println(\"======================================\");\n\n        // 场景一：未加锁的转账（演示线程安全问题）\n        System.out.println(\"\\n【场景一】未加锁转账（可能出错）：\");\n        testUnsafeTransfer();\n\n        // 重置账户状态\n        accountA.setBalance(1000);\n        accountB.setBalance(1000);\n\n        // 场景二：使用 synchronized 的转账（安全版本）\n        System.out.println(\"\\n【场景二】使用 synchronized 安全转账：\");\n        testSafeTransfer();\n\n        // 重置账户状态\n        accountA.setBalance(1000);\n        accountB.setBalance(1000);\n\n        // 场景三：死锁模拟（需要小心避免）\n        System.out.println(\"\\n【场景三】死锁模拟（观察程序卡住）：\");\n        testDeadlock();\n    }\n\n    /**\n     * 测试未加锁的转账 - 存在线程安全问题\n     * 两个线程同时转账，可能导致余额不一致\n     */\n    private static void testUnsafeTransfer() throws InterruptedException {\n        // 线程1：从A转账200到B\n        Thread t1 = new Thread(() -> {\n            for (int i = 0; i < 100; i++) {\n                unsafeTransfer(accountA, accountB, 200);\n            }\n        }, \"转账线程-1\");\n\n        // 线程2：从B转账100到A\n        Thread t2 = new Thread(() -> {\n            for (int i = 0; i < 100; i++) {\n                unsafeTransfer(accountB, accountA, 100);\n            }\n        }, \"转账线程-2\");\n\n        t1.start();\n        t2.start();\n        t1.join();  // 等待线程1结束\n        t2.join();  // 等待线程2结束\n\n        System.out.println(\"转账后状态：\");\n        System.out.println(accountA);\n        System.out.println(accountB);\n        // 预期总余额应为 2000，但实际可能因竞态条件而不同\n        System.out.println(\"总余额：\" + (accountA.getBalance() + accountB.getBalance()) + \"（应为2000）\");\n    }\n\n    /**\n     * 未加锁的转账操作 - 线程不安全\n     * 问题：check-then-act 操作不是原子性的\n     */\n    private static void unsafeTransfer(Account from, Account to, int amount) {\n        // 检查余额是否充足（检查阶段）\n        if (from.getBalance() >= amount) {\n            // 模拟业务处理延迟，增加线程安全问题发生的概率\n            try {\n                Thread.sleep(1);\n            } catch (InterruptedException e) {\n                Thread.currentThread().interrupt();\n            }\n\n            // 扣减和增加操作（执行阶段）\n            // 注意：这里两个操作不是原子性的，可能被其他线程中断\n            from.setBalance(from.getBalance() - amount);\n            to.setBalance(to.getBalance() + amount);\n        }\n    }\n\n    /**\n     * 测试使用 synchronized 的安全转账\n     * 通过锁机制保证操作的原子性\n     */\n    private static void testSafeTransfer() throws InterruptedException {\n        Thread t1 = new Thread(() -> {\n            for (int i = 0; i < 100; i++) {\n                safeTransfer(accountA, accountB, 200);\n            }\n        }, \"安全转账线程-1\");\n\n        Thread t2 = new Thread(() -> {\n            for (int i = 0; i < 100; i++) {\n                safeTransfer(accountB, accountA, 100);\n            }\n        }, \"安全转账线程-2\");\n\n        t1.start();\n        t2.start();\n        t1.join();\n        t2.join();\n\n        System.out.println(\"安全转账后状态：\");\n        System.out.println(accountA);\n        System.out.println(accountB);\n        System.out.println(\"总余额：\" + (accountA.getBalance() + accountB.getBalance()) + \"（正确应为2000）\");\n    }\n\n    /**\n     * 使用 synchronized 的安全转账操作\n     * 原理：synchronized 保证同一时刻只有一个线程可以执行该方法\n     * \n     * 注意：这里使用静态方法锁（锁住的是 BankTransferDemo.class 对象）\n     * 实际开发中建议使用更细粒度的锁\n     */\n    private static synchronized void safeTransfer(Account from, Account to, int amount) {\n        // 检查余额\n        if (from.getBalance() >= amount) {\n            try {\n                Thread.sleep(1);\n            } catch (InterruptedException e) {\n                Thread.currentThread().interrupt();\n            }\n\n            // 扣减和增加操作现在是在同一个锁保护下，是原子性的\n            from.setBalance(from.getBalance() - amount);\n            to.setBalance(to.getBalance() + amount);\n        }\n    }\n\n    /**\n     * 死锁模拟 - 两个线程互相持有对方需要的锁\n     * \n     * 死锁产生的四个必要条件：\n     * 1. 互斥：资源一次只能被一个线程使用\n     * 2. 持有并等待：线程持有资源时等待其他资源\n     * 3. 不可剥夺：资源只能由持有者释放\n     * 4. 循环等待：线程之间形成循环等待链\n     */\n    private static void testDeadlock() throws InterruptedException {\n        // 使用两个不同的锁对象\n        Object lockA = new Object();\n        Object lockB = new Object();\n\n        // 线程1：先锁A，再锁B\n        Thread t1 = new Thread(() -> {\n            synchronized (lockA) {\n                System.out.println(\"线程1：锁住了账户A\");\n                // 增加死锁概率\n                try { Thread.sleep(100); } catch (InterruptedException e) { }\n\n                synchronized (lockB) {\n                    System.out.println(\"线程1：锁住了账户B，开始转账\");\n                }\n            }\n        }, \"死锁线程-1\");\n\n        // 线程2：先锁B，再锁A（注意：顺序与线程1相反，容易导致死锁）\n        Thread t2 = new Thread(() -> {\n            synchronized (lockB) {\n                System.out.println(\"线程2：锁住了账户B\");\n                try { Thread.sleep(100); } catch (InterruptedException e) { }\n\n                synchronized (lockA) {\n                    System.out.println(\"线程2：锁住了账户A，开始转账\");\n                }\n            }\n        }, \"死锁线程-2\");\n\n        t1.start();\n        t2.start();\n\n        // 等待3秒后检查线程状态\n        t1.join(3000);\n        t2.join(3000);\n\n        // 排查死锁：检查线程状态\n        System.out.println(\"\\n--- 死锁排查 ---\");\n        System.out.println(\"线程1状态：\" + t1.getState());\n        System.out.println(\"线程2状态：\" + t2.getState());\n        if (t1.getState() == Thread.State.BLOCKED && t2.getState() == Thread.State.BLOCKED) {\n            System.out.println(\"检测到死锁！两个线程都处于 BLOCKED 状态\");\n            System.out.println(\"解决方法：统一锁的获取顺序，或使用 tryLock() 等机制\");\n        }\n    }\n}\n\n/**\n * 银行账户类\n * 演示了 synchronized 方法的使用\n */\nclass Account {\n    private String name;\n    private int balance;\n\n    public Account(String name, int balance) {\n        this.name = name;\n        this.balance = balance;\n    }\n\n    /**\n     * 同步方法：获取余额\n     * synchronized 修饰方法时，锁住的是当前对象（this）\n     */\n    public synchronized int getBalance() {\n        return balance;\n    }\n\n    /**\n     * 同步方法：设置余额\n     * 保证了读取和写入操作的原子性\n     */\n    public synchronized void setBalance(int balance) {\n        this.balance = balance;\n    }\n\n    @Override\n    public String toString() {\n        return name + \"的余额：\" + balance + \"元\";\n    }\n}\n```',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'0','Java',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-09 17:03:47','2026-06-09 17:03:47'),(177,'Java 程序设计 - 代码案例','code','medium',NULL,'```java\n/**\n * 多线程与并发教学案例：模拟银行转账系统\n * \n * 本案例演示：\n * 1. 线程安全问题（多个线程同时操作共享资源）\n * 2. synchronized 关键字的使用（解决线程安全）\n * 3. 死锁的产生与排查（两个线程互相等待对方释放资源）\n * \n * 场景：两个账户之间进行转账操作，多个线程同时执行转账\n */\npublic class BankTransferDemo {\n    \n    // 账户类，包含账户名和余额\n    static class Account {\n        private String name;\n        private int balance;\n        \n        public Account(String name, int balance) {\n            this.name = name;\n            this.balance = balance;\n        }\n        \n        // 转账方法：从当前账户向目标账户转账指定金额\n        // synchronized 关键字确保同一时刻只有一个线程能执行此方法\n        // 锁定的是当前对象（this），确保对当前账户余额的操作是原子性的\n        public synchronized void transfer(Account target, int amount) {\n            // 模拟转账前的业务处理耗时\n            try {\n                Thread.sleep(100);  // 让线程暂停100毫秒，更容易触发并发问题\n            } catch (InterruptedException e) {\n                e.printStackTrace();\n            }\n            \n            // 检查当前账户余额是否充足\n            if (this.balance >= amount) {\n                // 扣减当前账户余额\n                this.balance -= amount;\n                // 增加目标账户余额\n                target.balance += amount;\n                System.out.printf(\"[%s] %s 向 %s 转账 %d 元成功！当前余额：%d%n\",\n                        Thread.currentThread().getName(), \n                        this.name, target.name, amount, this.balance);\n            } else {\n                System.out.printf(\"[%s] %s 向 %s 转账 %d 元失败！余额不足，当前余额：%d%n\",\n                        Thread.currentThread().getName(),\n                        this.name, target.name, amount, this.balance);\n            }\n        }\n        \n        public int getBalance() {\n            return balance;\n        }\n        \n        public String getName() {\n            return name;\n        }\n    }\n    \n    public static void main(String[] args) {\n        // 创建两个账户，初始余额各1000元\n        Account accountA = new Account(\"账户A\", 1000);\n        Account accountB = new Account(\"账户B\", 1000);\n        \n        System.out.println(\"========== 演示线程安全问题 ==========\");\n        System.out.println(\"初始状态：账户A余额1000，账户B余额1000\");\n        System.out.println(\"注意：由于synchronized的保护，转账操作是线程安全的\");\n        System.out.println();\n        \n        // 创建多个线程同时进行转账操作\n        // 线程1：从A向B转账200元\n        Thread t1 = new Thread(() -> {\n            for (int i = 0; i < 3; i++) {\n                accountA.transfer(accountB, 200);\n                // 每次转账后暂停一下，让其他线程有机会执行\n                try {\n                    Thread.sleep(50);\n                } catch (InterruptedException e) {\n                    e.printStackTrace();\n                }\n            }\n        }, \"转账线程-1\");\n        \n        // 线程2：从B向A转账150元\n        Thread t2 = new Thread(() -> {\n            for (int i = 0; i < 3; i++) {\n                accountB.transfer(accountA, 150);\n                try {\n                    Thread.sleep(50);\n                } catch (InterruptedException e) {\n                    e.printStackTrace();\n                }\n            }\n        }, \"转账线程-2\");\n        \n        // 启动线程\n        t1.start();\n        t2.start();\n        \n        // 等待所有线程执行完毕\n        try {\n            t1.join();\n            t2.join();\n        } catch (InterruptedException e) {\n            e.printStackTrace();\n        }\n        \n        System.out.println();\n        System.out.println(\"========== 最终结果 ==========\");\n        System.out.println(\"账户A最终余额：\" + accountA.getBalance());\n        System.out.println(\"账户B最终余额：\" + accountB.getBalance());\n        System.out.println(\"总金额：\" + (accountA.getBalance() + accountB.getBalance()));\n        \n        System.out.println();\n        System.out.println(\"========== 死锁演示 ==========\");\n        System.out.println(\"注意：以下代码演示死锁，默认被注释掉，取消注释可观察死锁现象\");\n        \n        // 死锁示例代码（默认注释，避免死锁导致程序无法结束）\n        // 死锁发生条件：两个线程各自持有对方需要的锁，互相等待\n        /*\n        Account lockA = new Account(\"锁A\", 100);\n        Account lockB = new Account(\"锁B\", 100);\n        \n        // 线程1：先锁A，再锁B\n        Thread deadlockT1 = new Thread(() -> {\n            synchronized (lockA) {\n                System.out.println(\"线程1：获取了锁A\");\n                try { Thread.sleep(100); } catch (InterruptedException e) {}\n                synchronized (lockB) {\n                    System.out.println(\"线程1：获取了锁B\");\n                }\n            }\n        }, \"死锁线程-1\");\n        \n        // 线程2：先锁B，再锁A（与线程1获取锁的顺序相反）\n        Thread deadlockT2 = new Thread(() -> {\n            synchronized (lockB) {\n                System.out.println(\"线程2：获取了锁B\");\n                try { Thread.sleep(100); } catch (InterruptedException e) {}\n                synchronized (lockA) {\n                    System.out.println(\"线程2：获取了锁A\");\n                }\n            }\n        }, \"死锁线程-2\");\n        \n        deadlockT1.start();\n        deadlockT2.start();\n        // 此时程序可能卡住，两个线程互相等待对方释放锁\n        */\n        \n        System.out.println();\n        System.out.println(\"========== 死锁排查方法 ==========\");\n        System.out.println(\"1. 使用 jps 命令查看 Java 进程ID\");\n        System.out.println(\"2. 使用 jstack <进程ID> 查看线程堆栈信息\");\n        System.out.println(\"3. 在堆栈信息中搜索 \'deadlock\' 关键字\");\n        System.out.println(\"4. 分析线程的锁等待关系，找到死锁循环\");\n        System.out.println();\n        System.out.println(\"预防死锁的建议：\");\n        System.out.println(\"- 保持一致的锁获取顺序（总是先锁A再锁B）\");\n        System.out.println(\"- 使用 tryLock() 设置超时时间，避免无限等待\");\n        System.out.println(\"- 减少锁的持有时间，只在必要时加锁\");\n    }\n}\n```',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'0','Java 程序设计',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-09 17:13:14','2026-06-09 17:13:14'),(178,'Java 程序设计 - 思维导图','mindmap','medium',NULL,'{\"id\":\"root\",\"topic\":\"Java 程序设计\",\"children\":[{\"id\":\"n1\",\"topic\":\"Java 基础语法\",\"children\":[{\"id\":\"n2\",\"topic\":\"数据类型与变量\"},{\"id\":\"n3\",\"topic\":\"控制流程（if/for/while）\"},{\"id\":\"n4\",\"topic\":\"数组与字符串操作\"}]},{\"id\":\"n5\",\"topic\":\"面向对象编程\",\"children\":[{\"id\":\"n6\",\"topic\":\"类与对象\"},{\"id\":\"n7\",\"topic\":\"继承与多态\"},{\"id\":\"n8\",\"topic\":\"接口与抽象类\"}]},{\"id\":\"n9\",\"topic\":\"多线程与并发（重点）\",\"children\":[{\"id\":\"n10\",\"topic\":\"线程创建与生命周期\"},{\"id\":\"n11\",\"topic\":\"线程安全与同步\",\"children\":[{\"id\":\"n12\",\"topic\":\"synchronized 原理\"},{\"id\":\"n13\",\"topic\":\"锁机制（重入锁/读写锁）\"},{\"id\":\"n14\",\"topic\":\"死锁排查与预防\"}]},{\"id\":\"n15\",\"topic\":\"并发工具类\",\"children\":[{\"id\":\"n16\",\"topic\":\"线程池（ThreadPoolExecutor）\"},{\"id\":\"n17\",\"topic\":\"并发集合（ConcurrentHashMap）\"},{\"id\":\"n18\",\"topic\":\"原子类与CAS\"}]}]},{\"id\":\"n19\",\"topic\":\"资源与练习\",\"children\":[{\"id\":\"n20\",\"topic\":\"代码案例（多线程实战）\"},{\"id\":\"n21\",\"topic\":\"讲解文档（原理与规范）\"},{\"id\":\"n22\",\"topic\":\"练习题（查漏补缺）\"}]}]}',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'0','Java 程序设计',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-09 17:19:36','2026-06-09 17:19:36'),(179,'Java 程序设计 - 思维导图','mindmap','medium',NULL,'{\"id\":\"root\",\"topic\":\"Java 程序设计\",\"children\":[{\"id\":\"n1\",\"topic\":\"多线程与并发\",\"children\":[{\"id\":\"n1-1\",\"topic\":\"线程基础\",\"children\":[{\"id\":\"n1-1-1\",\"topic\":\"线程创建与启动\"},{\"id\":\"n1-1-2\",\"topic\":\"线程生命周期\"},{\"id\":\"n1-1-3\",\"topic\":\"线程优先级与调度\"}]},{\"id\":\"n1-2\",\"topic\":\"线程安全\",\"children\":[{\"id\":\"n1-2-1\",\"topic\":\"原子性问题\"},{\"id\":\"n1-2-2\",\"topic\":\"可见性问题\"},{\"id\":\"n1-2-3\",\"topic\":\"有序性问题\"}]},{\"id\":\"n1-3\",\"topic\":\"synchronized 原理\",\"children\":[{\"id\":\"n1-3-1\",\"topic\":\"对象锁与类锁\"},{\"id\":\"n1-3-2\",\"topic\":\"锁升级过程\"},{\"id\":\"n1-3-3\",\"topic\":\"底层实现：Monitor\"}]},{\"id\":\"n1-4\",\"topic\":\"死锁排查\",\"children\":[{\"id\":\"n1-4-1\",\"topic\":\"死锁产生条件\"},{\"id\":\"n1-4-2\",\"topic\":\"jstack 使用\"},{\"id\":\"n1-4-3\",\"topic\":\"避免策略\"}]},{\"id\":\"n1-5\",\"topic\":\"学习资源\",\"children\":[{\"id\":\"n1-5-1\",\"topic\":\"代码案例\"},{\"id\":\"n1-5-2\",\"topic\":\"讲解文档\"},{\"id\":\"n1-5-3\",\"topic\":\"练习题\"}]}]}]}',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'0','Java 程序设计',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-09 22:52:13','2026-06-09 22:52:13'),(180,'Java 程序设计 - 思维导图','mindmap','medium',NULL,'{\"id\":\"root\",\"topic\":\"Java 程序设计\",\"children\":[{\"id\":\"n1\",\"topic\":\"多线程与并发\",\"children\":[{\"id\":\"n2\",\"topic\":\"线程基础\",\"children\":[{\"id\":\"n3\",\"topic\":\"线程创建方式\"},{\"id\":\"n4\",\"topic\":\"线程生命周期\"},{\"id\":\"n5\",\"topic\":\"线程优先级与调度\"}]},{\"id\":\"n6\",\"topic\":\"线程安全\",\"children\":[{\"id\":\"n7\",\"topic\":\"synchronized 原理\"},{\"id\":\"n8\",\"topic\":\"volatile 关键字\"},{\"id\":\"n9\",\"topic\":\"Lock 接口与 ReentrantLock\"}]},{\"id\":\"n10\",\"topic\":\"死锁排查\",\"children\":[{\"id\":\"n11\",\"topic\":\"死锁产生条件\"},{\"id\":\"n12\",\"topic\":\"jstack 工具使用\"},{\"id\":\"n13\",\"topic\":\"避免死锁策略\"}]},{\"id\":\"n14\",\"topic\":\"并发工具\",\"children\":[{\"id\":\"n15\",\"topic\":\"线程池\"},{\"id\":\"n16\",\"topic\":\"CountDownLatch\"},{\"id\":\"n17\",\"topic\":\"CyclicBarrier\"},{\"id\":\"n18\",\"topic\":\"Semaphore\"}]},{\"id\":\"n19\",\"topic\":\"实战练习\",\"children\":[{\"id\":\"n20\",\"topic\":\"代码案例：线程安全计数器\"},{\"id\":\"n21\",\"topic\":\"代码案例：死锁模拟与排查\"},{\"id\":\"n22\",\"topic\":\"练习题：并发编程场景\"}]}]}]}',NULL,NULL,NULL,NULL,0.00,0,0,NULL,'0','Java 程序设计',NULL,0,NULL,NULL,NULL,'published',NULL,NULL,'2026-06-09 22:55:29','2026-06-09 22:55:29'),(181,'Java 程序设计 - 思维导图','mindmap','medium',NULL,'{\"id\":\"root\",\"topic\":\"Java 程序设计\",\"children\":[{\"id\":\"c1\",\"topic\":\"多线程与并发\",\"children\":[{\"id\":\"c1_1\",\"topic\":\"线程基础\",\"children\":[{\"id\":\"c1_1_1\",\"topic\":\"线程创建与启动\"},{\"id\":\"c1_1_2\",\"topic\":\"线程生命周期\"},{\"id\":\"c1_1_3\",\"topic\":\"线程优先级与调度\"}]},{\"id\":\"c1_2\",\"topic\":\"线程安全\",\"children\":[{\"id\":\"c1_2_1\",\"topic\":\"原子性与可见性\"},{\"id\":\"c1_2_2\",\"topic\":\"synchronized 原理\",\"children\":[{\"id\":\"c1_2_2_1\",\"topic\":\"对象锁与类锁\"},{\"id\":\"c1_2_2_2\",\"topic\":\"锁升级机制\"}]},{\"id\":\"c1_2_3\",\"topic\":\"volatile 关键字\"}]},{\"id\":\"c1_3\",\"topic\":\"并发工具\",\"children\":[{\"id\":\"c1_3_1\",\"topic\":\"Lock 与 ReentrantLock\"},{\"id\":\"c1_3_2\",\"topic\":\"线程池\",\"children\":[{\"id\":\"c