DROP TABLE IF EXISTS `student_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_profiles` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鐢诲儚ID',
  `student_id` bigint NOT NULL COMMENT '瀛︾敓ID',
  `major` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '涓撲笟',
  `grade` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '骞寸骇',
  `course` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '璇剧▼',
  `topic` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '褰撳墠瀛︿範涓婚?',
  `learning_goal` text COLLATE utf8mb4_unicode_ci COMMENT '瀛︿範鐩?爣',
  `knowledge_base` text COLLATE utf8mb4_unicode_ci COMMENT '鐭ヨ瘑鍩虹?',
  `cognitive_style` text COLLATE utf8mb4_unicode_ci COMMENT '璁ょ煡椋庢牸',
  `pace` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '瀛︿範鑺傚?',
  `weaknesses` json DEFAULT NULL COMMENT '钖勫急鐐?JSON鏁扮粍)',
  `mistake_patterns` json DEFAULT NULL COMMENT '鏄撻敊妯″紡(JSON鏁扮粍)',
  `resource_preference` json DEFAULT NULL COMMENT '璧勬簮鍋忓ソ(JSON鏁扮粍)',
  `overall_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_suggestions` text COLLATE utf8mb4_unicode_ci COMMENT '学习建议',
  `last_score` int DEFAULT NULL COMMENT '鏈?繎璇勪及鍒嗘暟',
  `last_suggestion` text COLLATE utf8mb4_unicode_ci COMMENT '鏈?繎寤鸿?',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `profile_data` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_id` (`student_id`),
  KEY `idx_topic` (`topic`),
  KEY `idx_overall_type` (`overall_type`),
  CONSTRAINT `student_profiles_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='瀛︾敓鐢诲儚琛';
