INSERT INTO `student_profiles` VALUES (1,4,NULL,NULL,'Java 程序设计','多线程与并发','掌握线程创建、同步机制和线程池使用','有一定编程基础，了解基本语法','偏好实操驱动学习','快速','[\"线程安全\", \"死锁排查\", \"synchronized 原理\"]','[\"线程状态混淆\", \"忘记释放锁\"]','[\"代码案例\", \"讲解文档\", \"练习题\"]',NULL,'从基础概念开始，系统学习核心知识点\n每天坚持30分钟代码实践\n使用思维导图梳理知识体系\n多做练习，巩固薄弱环节',71,NULL,'2026-05-26 20:22:40','2026-06-10 15:06:32','{\"overall_level\": {\"score\": 71}, \"knowledge_mastery\": {\"score\": 66}, \"learning_autonomy\": {\"score\": 66}, \"mistake_avoidance\": {\"score\": 75}, \"learning_goal_clarity\": {\"score\": 80}}'),(2,5,NULL,NULL,'Java 程序设计','集合框架','熟练使用 List/Map/Set，理解底层数据结构','基础薄弱，需要从概念讲起','偏好结构化讲解','慢速','[\"ArrayList vs LinkedList\", \"HashMap 底层\", \"泛型使用\"]','[\"集合遍历时修改\", \"类型选择不当\"]','[\"思维导图\", \"讲解文档\", \"练习题\"]',NULL,NULL,52,NULL,'2026-05-26 20:22:40','2026-05-26 20:22:40',NULL),(3,6,NULL,NULL,'Java 程序设计','IO流与文件操作','掌握字节流/字符流，理解 NIO 基础','有一定编程基础','偏好图解加代码实操','快速','[\"字节流 vs 字符流\", \"缓冲流原理\", \"NIO 概念\"]','[\"流未关闭\", \"字符编码错误\"]','[\"代码案例\", \"拓展阅读\", \"思维导图\"]',NULL,NULL,81,NULL,'2026-05-26 20:22:40','2026-05-26 20:22:40',NULL),(4,7,NULL,NULL,'Java 程序设计','异常处理与调试','掌握 try-catch-finally 和自定义异常','略有基础，写过简单程序','偏好练习驱动','中速','[\"异常链追踪\", \"finally 执行时机\", \"自定义异常\"]','[\"catch 顺序错误\", \"异常吞没\"]','[\"练习题\", \"讲解文档\", \"代码案例\"]',NULL,NULL,66,NULL,'2026-05-26 20:22:40','2026-05-26 20:22:40',NULL),(7,34,NULL,NULL,'JavaSE','JavaSE循环',NULL,'基础学习中，能理解概念但尚未达到熟练应用',NULL,'中速',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-08 15:56:44','2026-06-08 15:56:44',NULL),(100,100,NULL,NULL,'JavaSE','Java核心基础','扎实掌握Java SE全部核心知识，能独立开发控制台应用和简易桌面程序','熟练掌握Java SE基础语法、面向对象、集合、IO','视觉型','适中','[\"泛型深入\", \"反射机制\", \"网络编程\", \"正则表达式\"]','[\"泛型边界理解不透\", \"反射性能开销考虑不足\", \"IO流选择混淆\", \"异常处理不严谨\"]','[\"video\", \"code\", \"mindmap\"]','稳定提升型','1. 重点巩固泛型和反射机制，建议手写泛型工具类实战\n2. 系统学习网络编程，完成一个简易HTTP服务器\n3. 多做编程题，培养代码规范意识\n4. 深入学习集合源码，理解数据结构原理',78,'建议本周重点：深入理解HashMap源码和泛型擦除机制','2025-06-10 10:00:00','2026-06-10 08:00:00','{\"overall_level\": {\"level\": \"level_4\", \"score\": 78, \"evidence\": \"可独立完成JavaSE小项目\"}, \"knowledge_mastery\": {\"level\": \"level_4\", \"score\": 78, \"evidence\": \"完成150+练习题，正确率76%\"}, \"learning_autonomy\": {\"level\": \"level_5\", \"score\": 90, \"evidence\": \"持续每日学习345天\"}, \"mistake_avoidance\": {\"level\": \"level_3\", \"score\": 65, \"evidence\": \"错题重复率下降35%\"}, \"cognitive_adaptation\": {\"level\": \"level_3\", \"score\": 72, \"evidence\": \"偏好视觉型学习+代码实践\"}, \"learning_goal_clarity\": {\"level\": \"level_4\", \"score\": 85, \"evidence\": \"明确目标为扎实掌握JavaSE\"}}');
